\documentclass[border=10pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\begin{document}
\begin{tikzpicture}
\begin{axis}[
    xlabel={$y$}, ylabel={$z$}, zlabel={$x$},
    title={$x=y^2-z^2$ (hyperbolic paraboloid)},
    view={-60}{20},
    samples=40, domain=-2:2, y domain=-2:2,
    colormap/viridis,
    axis equal image,
    width=12cm, height=10cm
]
\addplot3[surf, opacity=0.8, shader=interp] {y^2-z^2};
\addplot3[red, very thick, samples=50] (x,0,x^2);
\addplot3[blue, very thick, samples=50] (0,x,-x^2);
\addplot3[magenta, very thick, samples=50] (x,x,0);
\addplot3[magenta, very thick, samples=50] (x,-x,0);
\end{axis}
\end{tikzpicture}
\end{document}

